// The RS-04 kit against the Python driver's golden vectors (no browser): node --test designer/kit/rs04/rs04.test.mjs
// vectors.json is generated by `python -m rig.rs04_vectors` from rig/rs04.py, rig/rs04_guard.py and rig/rs04_emu.py.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import * as P from './protocol.js';
import { createGuard } from './guard.js';
import { EmulatedRS04 } from './emulator.js';
import { createClient, Refused } from './client.js';
import { createEmulatorTransport, slcanDecode, slcanEncode, slcanLines } from './transports.js';

const V = JSON.parse(readFileSync(new URL('./vectors.json', import.meta.url), 'utf8'));
const frameOf = (f) => ({ id: f.id, data: P.unhex(f.data), ext: true });
const plain = (o) => JSON.parse(JSON.stringify(o));

test('the parameter table and the ranges are the Python driver\'s', () => {
  assert.deepEqual(V.ranges, { ...P.RS04 });
  assert.equal(Object.keys(P.PARAMS).length, V.params.length);
  for (const p of V.params) {
    const q = P.param(p.name);
    assert.deepEqual({ name: q.name, index: q.index, kind: q.kind, writable: q.writable, unit: q.unit, lo: q.lo, hi: q.hi }, p);
    assert.equal(P.param(p.index), q);
    assert.equal(P.param(p.name.toUpperCase()), q);
  }
  assert.throws(() => P.param('nope'), RangeError);
});

test('16-bit scaling matches float_to_uint and its inverse', () => {
  let n = 0;
  for (const c of V.scaling) {
    if (c.fn === 'f2u') assert.equal(P.f2u(c.x, c.lo, c.hi), c.u, `f2u(${c.x}, ${c.lo}, ${c.hi})`);
    else assert.equal(P.u2f(c.u, c.lo, c.hi), c.x, `u2f(${c.u}, ${c.lo}, ${c.hi})`);
    n++;
  }
  assert.ok(n > 60);
  assert.throws(() => P.f2u(NaN, 0, 1), RangeError);
  assert.throws(() => P.f2u(Infinity, 0, 1), RangeError);
});

test('every host frame is built byte for byte as rig/rs04.py builds it, and decodes the same', () => {
  for (const c of V.requests) {
    const f = P[c.fn](...c.args);
    assert.equal(f.id, c.frame.id, `${c.fn}(${c.args}) id`);
    assert.equal(P.hex(f.data), c.frame.data, `${c.fn}(${c.args}) data`);
    assert.equal(f.ext, true);
    assert.deepEqual(plain(P.parseRequest(f.id, f.data)), c.request, `${c.fn}(${c.args}) parsed`);
  }
  assert.throws(() => P.packSetId(1, 0), RangeError);
  assert.throws(() => P.packSetId(1, 128), RangeError);
  assert.throws(() => P.packWrite(1, 'VBUS', 1), RangeError);
  assert.throws(() => P.packMit(1, NaN, 0, 0, 0, 0), RangeError);
});

test('every motor frame parses as rig/rs04.py parses it', () => {
  for (const c of V.replies) {
    const m = P.parse(c.frame.id, P.unhex(c.frame.data));
    assert.deepEqual(plain(m), c.parsed, c.frame.data);
    if ('value' in c) assert.equal(P.value(m), c.value);
  }
});

test('parameter values pack and unpack as struct does', () => {
  for (const c of V.values) {
    const p = P.param(c.name), raw = P.packValue(p, c.value);
    assert.equal(P.hex(raw), c.raw, `${c.name} ${c.value}`);
    assert.equal(P.unpackValue(p, raw), c.back);
  }
  assert.throws(() => P.packValue(P.param('zero_sta'), 256), RangeError);
  assert.throws(() => P.packValue(P.param('canTimeout'), -1), RangeError);
});

test('the safety guard gives the bridge\'s verdicts on every scenario', () => {
  for (const [name, steps] of Object.entries(V.guard.scenarios)) {
    let now = 100;
    const g = createGuard(V.guard.limits, { clock: () => now });
    for (const [i, s] of steps.entries()) {
      const at = `${name}, step ${i}`;
      if (s.op === 'in') g.observe(frameOf(s.frame));
      else if (s.op === 'out') {
        const r = g.check({ ...frameOf(s.frame), ext: s.ext });
        assert.equal(r.code, s.code, `${at}: ${r.why}`);
        assert.equal(r.ok, s.ok, at);
      } else if (s.op === 'arm') { const r = g.arm(s.ids); assert.equal(r.code, s.code, at); assert.equal(r.ok, s.ok, at); }
      else if (s.op === 'disarm') g.disarm();
      else if (s.op === 'wait') now += s.s;
      else if (s.op === 'stop_targets') assert.deepEqual(g.stopTargets(), s.ids, at);
      now += 0.01;
    }
  }
});

test('the software motor answers a scripted session as rig/rs04_emu.py does', () => {
  for (const [name, rows] of Object.entries(V.emulator)) {
    let now = 0;
    const m = new EmulatedRS04({ id: 127, uid: P.unhex('0011223344556677'), clock: () => now, plant: name === 'plant' ? 'inertia' : null });
    for (const [i, r] of rows.entries()) {
      now += r.dt;
      const got = m.handle(frameOf(r.send)).map(f => ({ id: f.id, data: P.hex(f.data) }));
      assert.equal(got.length, r.reply.length, `${name} step ${i}`);
      for (const [j, f] of got.entries()) {
        assert.equal(f.id, r.reply[j].id, `${name} step ${i} id`);
        if (name === 'no_plant') { assert.equal(f.data, r.reply[j].data, `${name} step ${i}`); continue; }
        // the plant integrates in floating point: allow one count of the 16-bit fields
        const a = P.unhex(f.data), b = P.unhex(r.reply[j].data);
        for (let k = 0; k < 8; k += 2) assert.ok(Math.abs(((a[k] << 8) | a[k + 1]) - ((b[k] << 8) | b[k + 1])) <= 1, `${name} step ${i}: ${f.data} vs ${r.reply[j].data}`);
      }
    }
  }
});

test('slcan frames encode and decode', () => {
  const f = P.packWrite(2, 'limit_torque', 12);
  const line = slcanEncode(f);
  assert.match(line, /^T12[0-9A-F]{6}8[0-9A-F]{16}\r$/);
  const back = slcanDecode(line.slice(0, -1));
  assert.equal(back.id, f.id); assert.deepEqual([...back.data], [...f.data]); assert.equal(back.ext, true);
  assert.equal(slcanEncode({ id: 0x110, data: [1, 2], ext: false }), 't11020102\r');
  assert.deepEqual(slcanDecode('t1102AABB'), { id: 0x110, data: Uint8Array.from([0xAA, 0xBB]), ext: false });
  assert.equal(slcanDecode('T1234567884'), null);         // too short for its length
  assert.equal(slcanDecode('z'), null);
  const lines = slcanLines();
  assert.deepEqual(lines.push(new TextEncoder().encode('T0000000100\rT00')), ['T0000000100']);
  assert.deepEqual(lines.push(new TextEncoder().encode('0000020\r\x07')), ['T000000020']);
});

test('the client on the emulator: scan, setid, a guarded write, a refused one, and the arm sequence', async () => {
  const limits = V.guard.limits;
  const t = createEmulatorTransport({ motors: [{ id: 127, uid: P.unhex('0102030405060708') }], tickMs: 0 });
  const c = createClient(t, { limits });
  try {
    assert.deepEqual(await c.scan({ first: 120, last: 127, ms: 20 }), [{ id: 127, uid: '0102030405060708' }]);
    assert.equal(await c.version(127), '0.4.1.24');
    assert.equal(await c.setId(127, 1), 1);
    await assert.rejects(c.write(1, 'limit_torque', 13), (e) => e instanceof Refused && e.code === 'cap');
    await assert.rejects(c.write(1, 'canTimeout', 0), (e) => e instanceof Refused && e.code === 'watchdog');
    await assert.rejects(c.enable(1), (e) => e instanceof Refused && e.code === 'not-armed');
    await c.writeCheck(1, 'run_mode', 0);
    await c.writeCheck(1, 'canTimeout', 2000);
    await c.writeCheck(1, 'limit_torque', 3);
    c.arm([1]);
    const fb = await c.enable(1);
    assert.equal(fb.mode, 2);
    await assert.rejects(c.write(1, 'zero_sta', 1), (e) => e instanceof Refused && e.code === 'armed');
    await c.mit(1, 0.1, 0.5, 20, 1, 0);
    await assert.rejects(c.mit(1, 0.1, 0.5, 20, 1, 5), (e) => e.code === 'jog-torque');
    assert.deepEqual(c.stopAll(), [1, 127]);
    await new Promise(r => setTimeout(r, 5));
    assert.equal(t.bus.motors[0].mode, 0);
    await assert.rejects(c.enable(1), (e) => e.code === 'not-armed');
  } finally { c.close(); t.close(); }
});

test('the canTimeout watchdog drops a motor that hears nothing (a closed tab)', () => {
  let now = 0;
  const m = new EmulatedRS04({ id: 1, clock: () => now, plant: null });
  m.handle(P.packWrite(1, 'canTimeout', 2000));
  m.handle(P.packEnable(1));
  assert.equal(m.mode, 2);
  now += 0.05; m.watchdog(now); assert.equal(m.mode, 2);
  now += 0.2; m.watchdog(now); assert.equal(m.mode, 0);
});
